describe("resolveTracingConfig", () => {
  it("applies SPEC defaults and service defaults", () => {
    const c = resolveTracingConfig({ serviceName: " svc " });
    expect(c).toMatchObject({
      serviceName: "svc",
      protocol: "http/protobuf",
      sampler: "parentbased_always_on",
      samplerRatio: 1,
      propagators: ["tracecontext", "baggage"],
      batch: DEFAULT_TRACING_BATCH,
      compression: "gzip",
      setGlobal: true,
      headers: {},
      tls: {},
      resourceAttributes: {},
    });
    expect(c.endpoint).toBeUndefined();
    expect(Object.isFrozen(c)).toBe(true);
    const d = resolveTracingConfig(
      {
        serviceName: "svc",
        headers: { "x-org": "o" },
        batch: { scheduledDelayMs: 100 },
        propagators: ["B3", "datadog"],
        protocol: undefined,
      },
      {
        defaults: {
          protocol: "grpc",
          endpoint: "http://collector:4317",
          headers: { Authorization: "Bearer t" },
          batch: { maxQueueSize: 4096 },
        },
        extraPropagators: ["datadog"],
      },
    );
    expect(d).toMatchObject({
      protocol: "grpc",
      endpoint: "http://collector:4317",
      propagators: ["b3", "datadog"],
    });
    expect(d.headers).toEqual({ Authorization: "Bearer t", "x-org": "o" });
    expect(d.batch).toEqual({
      ...DEFAULT_TRACING_BATCH,
      maxQueueSize: 4096,
      scheduledDelayMs: 100,
    });
  });

  it("redacts headers and URL credentials in toString/toJSON", () => {
    const c = resolveTracingConfig({
      serviceName: "svc",
      serviceVersion: "1.0.0",
      environment: "test",
      endpoint: "https://user:pass@collector:4318/?api_key=abc",
      headers: { Authorization: "Bearer topsecret", "x-scope": "tenant" },
    });
    const text = c.toString();
    expect(text).not.toContain("topsecret");
    expect(text).not.toContain("pass@");
    expect(text).not.toContain("abc");
    expect(text).toContain("tenant");
    expect(JSON.stringify(c)).not.toContain("topsecret");
    expect(c.toJSON()).toMatchObject({ serviceVersion: "1.0.0", environment: "test" });
    expect(resolveTracingConfig({ serviceName: "s" }).toJSON()).not.toHaveProperty("endpoint");
  });

  it("rejects invalid values with ConfigError", () => {
    const bad: Parameters<typeof resolveTracingConfig>[0][] = [
      { serviceName: "" },
      { serviceName: "s", protocol: "udp" as "grpc" },
      { serviceName: "s", sampler: "sometimes" as SamplerName },
      { serviceName: "s", samplerRatio: 1.5 },
      { serviceName: "s", samplerRatio: Number.NaN },
      { serviceName: "s", propagators: ["xray"] },
      { serviceName: "s", batch: { maxQueueSize: 0 } },
      { serviceName: "s", batch: { maxExportBatchSize: 1.5 } },
      { serviceName: "s", batch: { maxQueueSize: 10, maxExportBatchSize: 20 } },
      { serviceName: "s", compression: "zstd" as "gzip" },
      { serviceName: "s", endpoint: "not a url" },
      { serviceName: "s", endpoint: "ftp://host" },
      { serviceName: "s", tls: { clientCertPath: "/c" } },
    ];
    for (const c of bad)
      expect(() => resolveTracingConfig(c), JSON.stringify(c)).toThrow(ConfigError);
    expect(() => resolveTracingConfig({} as { serviceName: string })).toThrow(/serviceName/);
  });
});

describe("samplers and propagators", () => {
  const traceId = "4bf92f3577b34da6a3ce929d0e0e4736";
  const decide = (name: SamplerName, ratio = 1) =>
    createSampler({ sampler: name, samplerRatio: ratio }).shouldSample(
      ROOT_CONTEXT,
      traceId,
      "s",
      SpanKind.INTERNAL,
      {},
      [],
    ).decision;

  it("builds every sampler", () => {
    expect(decide("always_on")).toBe(SamplingDecision.RECORD_AND_SAMPLED);
    expect(decide("always_off")).toBe(SamplingDecision.NOT_RECORD);
    expect(decide("traceidratio", 0)).toBe(SamplingDecision.NOT_RECORD);
    expect(decide("parentbased_always_on")).toBe(SamplingDecision.RECORD_AND_SAMPLED);
    expect(decide("parentbased_always_off")).toBe(SamplingDecision.NOT_RECORD);
    expect(decide("parentbased_traceidratio", 1)).toBe(SamplingDecision.RECORD_AND_SAMPLED);
  });

  it("builds composite propagators including b3 and service extras", () => {
    const sc = { traceId, spanId: "00f067aa0ba902b7", traceFlags: 1 };
    const ctx = trace.setSpanContext(ROOT_CONTEXT, sc);
    const carrier: Record<string, string> = {};
    const setter = { set: (c: Record<string, string>, k: string, v: string) => (c[k] = v) };
    createPropagator(["tracecontext", "baggage", "b3", "b3multi", "none", "custom", "missing"], {
      custom: (): TextMapPropagator => ({
        inject: (_c, car: Record<string, string>) => (car["x-custom"] = "1"),
        extract: (c) => c,
        fields: () => ["x-custom"],
      }),
    }).inject(ctx, carrier, setter);
    expect(carrier.traceparent).toBe(`00-${traceId}-00f067aa0ba902b7-01`);
    expect(carrier.b3).toBe(`${traceId}-00f067aa0ba902b7-1`);
    expect(carrier["x-b3-traceid"]).toBe(traceId);
    expect(carrier["x-custom"]).toBe("1");
    const none: Record<string, string> = {};
    createPropagator(["none"]).inject(ctx, none, setter);
    expect(none).toEqual({});
  });
});

